/* 堤麟画板 · 工作用 CMYK「U.S. Web Coated (SWOP) v2」的近似：SWOP 印刷特征（CMYK → Lab D50，相对比色、纸白＝L* 100）9⁴ 格点查表＋四线性内插。
   资料来源：colord 随附的 SWOP_TR003_coated_3.icc（特征资料＝CGATS TR 003 SWOP Coated #3，NPES；描述档 CC0），用 LittleCMS 2.14 算格点。
   这不是 Adobe 的 USWebCoatedSWOP.icc（那份不能随附）；分色（黑版生成 GCR、总墨量 300%、黑版上限）在 menus/impl/ps-image.js 照 PS 预设调过，
   让常见颜色的 CMYK 数字跟 PS 拾色器显示的接近（纯红 0/99/100/0、50% 灰 52/43/43/8、黑 75/68/67/90 一带）。
   SwopCmyk.labInto(c, m, y, k（0..1）, out) → out＝[L*, a*, b*]；paperLab＝纸白的绝对 Lab。 */
(function(){
'use strict';
if (window.SwopCmyk) return;
const N = 9, B64 = '';
let T = null;
function table(){
  if (T) return T;
  const s = atob(B64), u = new Uint16Array(s.length / 2);
  for (let i = 0; i < u.length; i++) u[i] = s.charCodeAt(i * 2) | (s.charCodeAt(i * 2 + 1) << 8);
  T = new Float32Array(u.length);
  for (let i = 0; i < u.length; i += 3){ T[i] = u[i] / 655.35; T[i + 1] = u[i + 1] / 256 - 128; T[i + 2] = u[i + 2] / 256 - 128; }
  return T;
}
const S = N - 1, cl = v => v < 0 ? 0 : v > 1 ? 1 : v;
window.SwopCmyk = {
  n:N, paperLab:[92.5085, 0.0252, 0.026], source:'SWOP TR003 Coated #3 (CGATS/NPES) via colord + LittleCMS',
  labInto(c0, c1, c2, c3, out){
    const t = table(), v = [cl(c0) * S, cl(c1) * S, cl(c2) * S, cl(c3) * S], i0 = v.map(x => Math.min(Math.floor(x), S - 1)), f = v.map((x, j) => x - i0[j]);
    let L = 0, a = 0, b = 0;
    for (let m = 0; m < 16; m++){
      let w = 1, idx = 0;
      for (let j = 0; j < 4; j++){ const bit = (m >> (3 - j)) & 1; w *= bit ? f[j] : 1 - f[j]; idx = idx * N + i0[j] + bit; }
      if (w === 0) continue;
      const o = idx * 3; L += w * t[o]; a += w * t[o + 1]; b += w * t[o + 2];
    }
    out[0] = L; out[1] = a; out[2] = b; return out;
  },
  lab(c){ return this.labInto(c[0], c[1], c[2], c[3], [0, 0, 0]); }
};
})();

/* sRGB（8 位）→ 已经压进 SWOP 色域的 Lab（相对比色＋黑场补偿；LittleCMS 用同一份 SWOP 特征算的 17³ 格点）：
   出色域的颜色（纯蓝、纯绿…）照 ICC 相对比色表的压法进来，再交给 ps-image.js 的分色（PS 那套 GCR／总墨量）解 CMYK */
(function(){
const N = 17, B64 = '';
let T = null;
const tab = () => { if (T) return T; const s = atob(B64), u = new Uint16Array(s.length / 2); for (let i = 0; i < u.length; i++) u[i] = s.charCodeAt(i * 2) | (s.charCodeAt(i * 2 + 1) << 8);
  T = new Float32Array(u.length); for (let i = 0; i < u.length; i += 3){ T[i] = u[i] / 655.35; T[i + 1] = u[i + 1] / 256 - 128; T[i + 2] = u[i + 2] / 256 - 128; } return T; };
window.SwopCmyk.mapLab = function(r, g, b){
  const t = tab(), S = N - 1, v = [r, g, b].map(x => Math.max(0, Math.min(255, x)) / 255 * S), i0 = v.map(x => Math.min(Math.floor(x), S - 1)), f = v.map((x, j) => x - i0[j]);
  const out = [0, 0, 0];
  for (let m = 0; m < 8; m++){
    let w = 1, idx = 0;
    for (let j = 0; j < 3; j++){ const bit = (m >> (2 - j)) & 1; w *= bit ? f[j] : 1 - f[j]; idx = idx * N + i0[j] + bit; }
    if (w === 0) continue;
    out[0] += w * t[idx * 3]; out[1] += w * t[idx * 3 + 1]; out[2] += w * t[idx * 3 + 2];
  }
  return out;
};
})();
/* ── sRGB→CMYK 预算表（menus/impl/ps-image.js 的 SWOP 分色逐格解出来的：17³ 格、相对比色／可感知＋黑场补偿）＋色域 ΔE 表（相对比色不补黑，ΔE76）──
   拾色器、文件 ▸ 模式 ▸ CMYK、视图 ▸ 校样颜色／色域警告、AI 分色预览都查这几张 ⇒ 同一个颜色在各处是同一组 CMYK（现解一整份要十几秒，查表是即时的）。
   重算：在页面里设 SwopCmyk.noTables = true 后照 格点生成脚本 那样逐格叫 PsImageMode.cms.rgbToCmyk。 */
(function(){
const N = 17, RAW = {relative:'', perceptual:''}, DE = '', T = {};
const dec = b64 => { const s = atob(b64), out = new Float32Array(s.length / 2); for (let i = 0; i < out.length; i++) out[i] = (s.charCodeAt(i * 2) | (s.charCodeAt(i * 2 + 1) << 8)) / 65535; return out; };
const S = window.SwopCmyk;
S.rgbN = N;
S.rgbTable = it => RAW[it] ? (T[it] || (T[it] = dec(RAW[it]))) : null;
const tri = (L, ch, r, g, b) => {
  const M = N - 1, f = [r, g, b].map(v => Math.max(0, Math.min(255, v)) / 255 * M), i0 = f.map(v => Math.min(M - 1, Math.floor(v))), d = f.map((v, i) => v - i0[i]), out = new Array(ch).fill(0);
  for (let a = 0; a < 2; a++) for (let bb = 0; bb < 2; bb++) for (let c = 0; c < 2; c++){
    const w = (a ? d[0] : 1 - d[0]) * (bb ? d[1] : 1 - d[1]) * (c ? d[2] : 1 - d[2]); if (!w) continue;
    const j = (((i0[0] + a) * N + i0[1] + bb) * N + i0[2] + c) * ch;
    for (let k = 0; k < ch; k++) out[k] += L[j + k] * w;
  }
  return out;
};
S.sampleRgb = (it, r, g, b) => tri(S.rgbTable(it), 4, r, g, b);
let G = null;
S.gamutDE = (r, g, b) => { if (!G){ const s = atob(DE); G = new Float32Array(s.length); for (let i = 0; i < s.length; i++) G[i] = s.charCodeAt(i) / 4; } return tri(G, 1, r, g, b)[0]; };
})();
